7	@Injectable({ providedIn: 'root' })
8	export class EventService {
9	  private readonly http = inject(HttpClient);
10	
11	  getEvents(filter?: EventListFilter): Observable<EventListItem[]> {
12	    let params = new HttpParams();
13	    if (filter?.from) {
14	      params = params.set('from', filter.from);
